 function capture(p){if(applying||!isDraft(p))return;const d=activeDoc(p);if(!d)return;const blocks=clone(p.blocks),signature=JSON.stringify(blocks);if(signature===d.signature)return;d.blocks=blocks;d.history=clone(p.history||[]);d.note=clone(p.note);d.signature=signature;d.sequence=(d.sequence||0)+1;d.changedAt=new Date().toISOString();p.ownedDraft={bindingId:d.binding.id,sequence:d.sequence};if(!['Conflict','Recover save'].includes(d.status)&&!(d.status==='Save unavailable'&&d.pending))d.status='Unsaved changes';persist();original.save();cue(p);schedule(d);}
